import React, { useState } from "react";
import { View, StyleSheet, Alert, Image, TouchableOpacity, Text } from "react-native";
import DocumentPicker from "react-native-document-picker";
import axios from "axios";

const DocumentUpload = () => {
  const [selectedFile, setSelectedFile] = useState(null);

  // Handle document selection
  const pickDocument = async () => {
    try {
      const res = await DocumentPicker.pickSingle({
        type: [DocumentPicker.types.allFiles], // Accept all file types
      });

      setSelectedFile(res);
    } catch (err) {
      if (DocumentPicker.isCancel(err)) {
        Alert.alert("Cancelled", "You did not select any document.");
      } else {
        console.error("DocumentPicker Error: ", err);
      }
    }
  };

  // Handle document upload
  const uploadDocument = async () => {
    if (!selectedFile) {
      Alert.alert("No File", "Please select a document first.");
      return;
    }

    const formData = new FormData();
    formData.append("file", {
      uri: selectedFile.uri,
      name: selectedFile.name,
      type: selectedFile.type,
    });

    formData.append("createdBy", "dd606a34-6e0a-4b0f-8cfd-8e9138267639");
    formData.append("id", "eeb22745-631b-41a4-a805-08dd41ebc15a");

    try {
      const response = await axios.post(
        "https://predart003-001-site1.anytempurl.com/api/Doctor/SaveDocuments",
        formData,
        {
          headers: { "Content-Type": "multipart/form-data" },
        }
      );

      Alert.alert("Success", "Document uploaded successfully!");
      console.log("Upload Response:", response.data);
    } catch (error) {
      console.error("Upload Error:", error);
      Alert.alert("Upload Failed", "Something went wrong. Try again.");
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Upload Document</Text>

      {/* File Picker Button */}
      <TouchableOpacity style={styles.button} onPress={pickDocument}>
        <Text style={styles.buttonText}>Select Document</Text>
      </TouchableOpacity>

      {/* Show Selected File */}
      {selectedFile && (
        <View style={styles.filePreview}>
          <Text style={styles.fileName}>{selectedFile.name}</Text>
        </View>
      )}

      {/* Upload Button */}
      <TouchableOpacity style={styles.uploadButton} onPress={uploadDocument}>
        <Text style={styles.uploadButtonText}>Upload</Text>
      </TouchableOpacity>
    </View>
  );
};

// Styles
const styles = StyleSheet.create({
  container: { flex: 1, justifyContent: "center", alignItems: "center", padding: 20, backgroundColor: "#F5F5F5" },
  title: { fontSize: 24, fontWeight: "bold", marginBottom: 20, color: "#333" },
  button: { backgroundColor: "#007BFF", padding: 12, borderRadius: 8, marginBottom: 15 },
  buttonText: { color: "#FFF", fontSize: 16, fontWeight: "bold" },
  filePreview: { marginTop: 10, padding: 10, borderRadius: 8, backgroundColor: "#FFF", width: "90%", alignItems: "center" },
  fileName: { fontSize: 14, fontWeight: "600", color: "#555" },
  uploadButton: { backgroundColor: "#28A745", padding: 12, borderRadius: 8, marginTop: 15 },
  uploadButtonText: { color: "#FFF", fontSize: 16, fontWeight: "bold" },
});

export default DocumentUpload;
